const fs=require('fs'),path=require('path'),{chromium}=require('playwright');
const a=process.argv.slice(2),arg=(n,f='')=>{const i=a.indexOf(n);return i>=0&&a[i+1]?a[i+1]:f};
const base=arg('--url','http://localhost/greenportal').replace(/\/$/,''),empresa=arg('--empresa','Modelo'),usuario=arg('--usuario','admin'),senha=arg('--senha', process.env.GREEN_TEST_PASSWORD || ''),cdp=arg('--cdp',''),out=path.resolve(arg('--saida','tests/resultado-checklist-checkbox-requisitos-legais-20260924.json'));
const result={startedAt:new Date().toISOString(),checks:[],status:'REPROVADO'};const check=(n,o,d='')=>{result.checks.push({name:n,ok:!!o,details:d});console.log(`${o?'PASS':'FAIL'} - ${n}${d?`: ${d}`:''}`);if(!o)throw new Error(n)};
async function main(){let b;try{b=cdp?await chromium.connectOverCDP(cdp):await chromium.launch({headless:true});const c=cdp?(b.contexts()[0]||await b.newContext()):await b.newContext();const p=cdp?(c.pages()[0]||await c.newPage()):await c.newPage();p.setDefaultTimeout(20000);
await p.goto(base+'/index.php',{waitUntil:'domcontentloaded'});await p.locator('#empresa').selectOption({label:empresa}).catch(()=>p.locator('#empresa').selectOption({value:empresa}));await p.locator('#userid').fill(usuario);await p.locator('#senha').fill(senha);await p.locator('form.login-form button[type="submit"]').click();await p.waitForURL(/\/principal\/main\.php/);await p.locator('[data-sidebar-toggle]').click().catch(()=>{});await p.locator('#menuSearch').fill('Requisitos legais');await p.locator('button[data-open-tab][data-tab-url*="modulolegal_requisitoslegais.php"]').click();const main=p.frameLocator('iframe[src*="modulolegal_requisitoslegais.php"]');await main.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});const row=main.locator('#requisitosLegaisBatchGrid tbody tr').first();await row.click();const law=(await row.locator('[data-column="CODLEGISLACAO"]').innerText()).trim(),unit=(await row.locator('[data-column="CODUNIDADE"]').innerText()).trim();const open=main.locator('[data-open-requisito-popup="checklist"]');await open.click();
async function getFrame(){const popup=p.locator('#greenPortalTransacaoModal');await popup.waitFor({state:'visible'});const f=p.frameLocator('#greenPortalTransacaoModal iframe');await f.locator('#checklistQuestionsGrid').waitFor({state:'visible'});return {popup,f}}
let {popup,f}=await getFrame();const unchecked=f.locator('tbody tr').filter({has:f.locator('input[type="checkbox"]:not(:checked)')}).first();check('Linha de checklist não associada localizada',await unchecked.count()===1,`lei=${law},unidade=${unit}`);const qid=await unchecked.getAttribute('data-question-id');
async function saveAndReopen(){const response=p.waitForResponse(r=>r.request().method()==='POST'&&r.url().includes('manutencaolegalrequisitoslegais_checklist.php')&&String(r.request().postData()||'').includes('save_checklist'),{timeout:15000}).catch(()=>null);await f.locator('[data-save]').click();const confirm=p.locator('[data-popup-mensagem-confirm]').last();await confirm.waitFor({state:'visible',timeout:10000});await confirm.click();const saved=await response;check('Salvamento do Checklist respondido',!!saved&&saved.status()===200, saved?`HTTP ${saved.status()}`:'sem resposta');const iframe=popup.locator('iframe');const src=await iframe.getAttribute('src');await iframe.evaluate((el,url)=>{el.src=url},src);({popup,f}=await getFrame())}
await unchecked.locator('input[type="checkbox"]').check();await saveAndReopen();let target=f.locator(`tbody tr[data-question-id="${qid}"] input[type="checkbox"]`);check('Checkbox marcado e persistido após reabrir',await target.isChecked(),`pergunta=${qid}`);await target.uncheck();await saveAndReopen();target=f.locator(`tbody tr[data-question-id="${qid}"] input[type="checkbox"]`);check('Checkbox desmarcado e persistido após reabrir',!(await target.isChecked()),`pergunta=${qid}`);result.status='APROVADO'}catch(e){result.error=e.message;throw e}finally{result.finishedAt=new Date().toISOString();fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(result,null,2));if(b&&!cdp)await b.close()}}main().catch(e=>{console.error(`ERRO FATAL: ${e.stack||e.message}`);process.exit(1)});
